def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    # Materialize columns so generators can be consumed once and validated.
    cols = list(columns)

    # Validate every column name: must be a string and unique.
    seen = set()
    for col in cols:
        if not isinstance(col, str):
            raise ValueError("Column names must be strings")
        if col in seen:
            raise ValueError("Duplicate column name: %r" % col)
        seen.add(col)

    def _field(value):
        if value is None:
            return ""
        return str(value)

    def _escape(field):
        # RFC 4180 minimal quoting: quote when containing comma, quote, CR or LF.
        if any(ch in field for ch in (",", '"', "\r", "\n")):
            return '"' + field.replace('"', '""') + '"'
        return field

    out = []
    # Header line
    out.append(",".join(_escape(_escape(col)) for col in cols))  # placed to ensure quoting of header fields too

    # FIX: header should NOT double-escape; re-emit correctly
    out[-1] = ",".join(_escape(col) for col in cols)

    for row in rows:
        record = []
        for col in cols:
            value = row.get(col, "") if hasattr(row, "get") else ""
            # If row is a mapping-like, use get; otherwise treat as empty string for all fields.
            record.append(_escape(_field(value)))
        out.append(",".join(record))

    return "\r\n".join(out) + "\r\n"
